## Type

```tsx
type TagDescription = {
	tag: string;
	props: Record<string, unknown>;
	setting?: {
		close?: boolean;
		escape?: boolean;
	};
	id: string;
	name?: string;
	ref?: Element;
};

function useHead(tag: TagDescription): void;
```

### Basic usage

```tsx
import { createUniqueId } from "solid-js";
import { MetaProvider, useHead } from "@solidjs/meta";

function RssLink() {
	useHead({
		tag: "link",
		id: createUniqueId(),
		props: {
			rel: "alternate",
			type: "application/rss+xml",
			title: "Solid RSS",
			href: "/rss.xml",
		},
	});
}

export default function Root() {
	return (
		<MetaProvider>
			<RssLink />
		</MetaProvider>
	);
}
```

### Script contents

```tsx
import { createUniqueId } from "solid-js";
import { MetaProvider, useHead } from "@solidjs/meta";

function JsonLd() {
	const jsonLD = JSON.stringify({
		"@context": "https://schema.org",
		"@type": "WebSite",
		name: "Solid Docs",
		url: "https://docs.solidjs.com/",
	});

	useHead({
		tag: "script",
		setting: { close: true, escape: false },
		id: createUniqueId(),
		props: {
			type: "application/ld+json",
			children: jsonLD,
		},
	});
}

export default function Root() {
	return (
		<MetaProvider>
			<JsonLd />
		</MetaProvider>
	);
}
```

### Delete `<MetaProvider>`

The head registry is ambient — the provider and `MetaContext` no longer exist.
Remove the wrapper:

```tsx del={1,5,7}
import { MetaProvider } from "@solidjs/meta";

export default function App() {
	return (
		<MetaProvider>
			<Layout />
		</MetaProvider>
	);
}
```

